// Shipping for one order, in cents. Never discounted, and the free-shipping
// threshold reads the plain sum of the lines, before any discount and tax.
function shippingCents(order, plainGoods) {
  if (order.shipping === "express") return 1500;
  return plainGoods < 5000 ? 500 : 0;
}

// The total of one order, in cents.
function orderTotal(order) {
  const plainGoods = sum(order.lines, (line) => line.unitCents * line.quantity);
  let goods = sum(order.lines, lineCents);
  goods = couponed(goods, order.coupon);
  return goods + shippingCents(order, plainGoods);
}

